using System;
using PX.Data;
using PX.Data.BQL;

namespace StudioB.AcuOps
{
    [PXTable("UsrAuditTrailView")]
    [PXCacheName("Audit Trail")]
    public class UsrAuditTrailView : IBqlTable
    {
        public static bool IsActive() => true;

        #region CompanyID
        public abstract class companyID : BqlInt.Field<companyID> { }
        [PXDBInt(IsKey = true)]
        [PXUIField(DisplayName = "Company ID", Visible = false)]
        public virtual int? CompanyID { get; set; }
        #endregion

        #region BatchID
        public abstract class batchID : BqlGuid.Field<batchID> { }
        [PXDBGuid(IsKey = true)]
        [PXUIField(DisplayName = "Batch ID", Visible = false)]
        public virtual Guid? BatchID { get; set; }
        #endregion

        #region ChangeID
        public abstract class changeID : BqlInt.Field<changeID> { }
        [PXDBInt(IsKey = true)]
        [PXUIField(DisplayName = "Change ID", Visible = false)]
        public virtual int? ChangeID { get; set; }
        #endregion

        #region ScreenID
        public abstract class screenID : BqlString.Field<screenID> { }
        [PXDBString(8, IsUnicode = true)]
        [PXUIField(DisplayName = "Screen ID")]
        public virtual string ScreenID { get; set; }
        #endregion

        #region UserID
        public abstract class userID : BqlGuid.Field<userID> { }
        [PXDBGuid]
        [PXUIField(DisplayName = "User ID", Visible = false)]
        public virtual Guid? UserID { get; set; }
        #endregion

        #region Username
        public abstract class username : BqlString.Field<username> { }
        [PXDBString(256, IsUnicode = true)]
        [PXUIField(DisplayName = "User")]
        public virtual string Username { get; set; }
        #endregion

        #region ChangeDate
        public abstract class changeDate : BqlDateTime.Field<changeDate> { }
        [PXDBDate(PreserveTime = true)]
        [PXUIField(DisplayName = "Date")]
        public virtual DateTime? ChangeDate { get; set; }
        #endregion

        #region OperationDesc
        public abstract class operationDesc : BqlString.Field<operationDesc> { }
        [PXDBString(50, IsUnicode = true)]
        [PXUIField(DisplayName = "Operation")]
        public virtual string OperationDesc { get; set; }
        #endregion

        #region TableName
        public abstract class tableName : BqlString.Field<tableName> { }
        [PXDBString(128, IsUnicode = true)]
        [PXUIField(DisplayName = "Table")]
        public virtual string TableName { get; set; }
        #endregion

        #region CombinedKeyDisplay
        public abstract class combinedKeyDisplay : BqlString.Field<combinedKeyDisplay> { }
        [PXDBString(IsUnicode = true)]
        [PXUIField(DisplayName = "Record Key")]
        public virtual string CombinedKeyDisplay { get; set; }
        #endregion

        #region ModifiedFieldsDisplay
        public abstract class modifiedFieldsDisplay : BqlString.Field<modifiedFieldsDisplay> { }
        [PXDBString(IsUnicode = true)]
        [PXUIField(DisplayName = "Modified Fields")]
        public virtual string ModifiedFieldsDisplay { get; set; }
        #endregion
    }
}

Sql.CDATA:
-- REVIEWED: gi-sql-safe
-- StudioBAuditTrail GI installer — scoped by DesignID + CompanyID, no blanket wipes.
-- Upsert pattern: delete existing, insert fresh.
-- Also cleans up old UserAuditTrail GI from prior versions.

DECLARE @CompanyID int = 2;
DECLARE @DesignID uniqueidentifier;
DECLARE @OldDesignID uniqueidentifier;
DECLARE @Now datetime = GETUTCDATE();

-- Discover CompanyID from a known GI
SELECT TOP 1 @CompanyID = CompanyID FROM GIDesign WHERE Name = 'InventoryAllocationDetail';

-- Clean up old UserAuditTrail GI (from prior version)
SELECT @OldDesignID = DesignID FROM GIDesign WHERE Name = 'UserAuditTrail' AND CompanyID = @CompanyID;
IF @OldDesignID IS NOT NULL
BEGIN
    DELETE FROM GIFilter   WHERE DesignID = @OldDesignID AND CompanyID = @CompanyID;
    DELETE FROM GISort     WHERE DesignID = @OldDesignID AND CompanyID = @CompanyID;
    DELETE FROM GIResult   WHERE DesignID = @OldDesignID AND CompanyID = @CompanyID;
    DELETE FROM GIGroupBy  WHERE DesignID = @OldDesignID AND CompanyID = @CompanyID;
    DELETE FROM GIOn       WHERE DesignID = @OldDesignID AND CompanyID = @CompanyID;
    DELETE FROM GIRelation WHERE DesignID = @OldDesignID AND CompanyID = @CompanyID;
    DELETE FROM GIWhere    WHERE DesignID = @OldDesignID AND CompanyID = @CompanyID;
    DELETE FROM GITable    WHERE DesignID = @OldDesignID AND CompanyID = @CompanyID;
    DELETE FROM GIDesign   WHERE DesignID = @OldDesignID AND CompanyID = @CompanyID;
END

-- Clean up existing StudioBAuditTrail GI (for re-deploy idempotency)
SELECT @DesignID = DesignID FROM GIDesign WHERE Name = 'StudioBAuditTrail' AND CompanyID = @CompanyID;
IF @DesignID IS NOT NULL
BEGIN
    DELETE FROM GIFilter   WHERE DesignID = @DesignID AND CompanyID = @CompanyID;
    DELETE FROM GISort     WHERE DesignID = @DesignID AND CompanyID = @CompanyID;
    DELETE FROM GIResult   WHERE DesignID = @DesignID AND CompanyID = @CompanyID;
    DELETE FROM GIGroupBy  WHERE DesignID = @DesignID AND CompanyID = @CompanyID;
    DELETE FROM GIOn       WHERE DesignID = @DesignID AND CompanyID = @CompanyID;
    DELETE FROM GIRelation WHERE DesignID = @DesignID AND CompanyID = @CompanyID;
    DELETE FROM GIWhere    WHERE DesignID = @DesignID AND CompanyID = @CompanyID;
    DELETE FROM GITable    WHERE DesignID = @DesignID AND CompanyID = @CompanyID;
    DELETE FROM GIDesign   WHERE DesignID = @DesignID AND CompanyID = @CompanyID;
END

-- Generate new DesignID
SET @DesignID = NEWID();

-- GI header (ExposeViaOData=1 for REST API access)
INSERT INTO GIDesign (CompanyID, DesignID, Name, Description, ExposeViaOData, CreatedDateTime, LastModifiedDateTime)
VALUES (@CompanyID, @DesignID, 'StudioBAuditTrail', 'AcuOps Audit Trail - user change history with readable field data', 1, @Now, @Now);

-- Primary table reference (required — GI must know which DAC to query)
INSERT INTO GITable (CompanyID, DesignID, Alias, Name, IsActive)
VALUES (@CompanyID, @DesignID, 'UsrAuditTrailView', 'StudioB.AcuOps.UsrAuditTrailView', 1);

-- Result columns (7 visible)
INSERT INTO GIResult (CompanyID, DesignID, LineNbr, ObjectName, Field, IsVisible, SortOrder)
VALUES
    (@CompanyID, @DesignID, 1, 'UsrAuditTrailView', 'ChangeDate', 1, 0),
    (@CompanyID, @DesignID, 2, 'UsrAuditTrailView', 'Username', 1, 0),
    (@CompanyID, @DesignID, 3, 'UsrAuditTrailView', 'ScreenID', 1, 0),
    (@CompanyID, @DesignID, 4, 'UsrAuditTrailView', 'OperationDesc', 1, 0),
    (@CompanyID, @DesignID, 5, 'UsrAuditTrailView', 'TableName', 1, 0),
    (@CompanyID, @DesignID, 6, 'UsrAuditTrailView', 'CombinedKeyDisplay', 1, 0),
    (@CompanyID, @DesignID, 7, 'UsrAuditTrailView', 'ModifiedFieldsDisplay', 1, 0);

-- Sort: ChangeDate descending
INSERT INTO GISort (CompanyID, DesignID, LineNbr, DataFieldName, IsDescending)
VALUES (@CompanyID, @DesignID, 1, 'UsrAuditTrailView.ChangeDate', 1);

-- Filters (5 user-facing)
-- Condition codes: 0=Equals, 2=Contains, 6=Between
INSERT INTO GIFilter (CompanyID, DesignID, LineNbr, DataFieldName, Condition, IsDefault)
VALUES
    (@CompanyID, @DesignID, 1, 'UsrAuditTrailView.ChangeDate', 6, 1),
    (@CompanyID, @DesignID, 2, 'UsrAuditTrailView.ScreenID', 2, 1),
    (@CompanyID, @DesignID, 3, 'UsrAuditTrailView.Username', 2, 1),
    (@CompanyID, @DesignID, 4, 'UsrAuditTrailView.TableName', 2, 1),
    (@CompanyID, @DesignID, 5, 'UsrAuditTrailView.OperationDesc', 0, 1);
